codashop.cssOverride:
body[data-theme='theme-preset--store-mgsdelta'] {
  --x-ref-primary: #009600;
  --x-ref-secondary: #C4E39C;
  --x-ref-tertiary: #007E00;
  --x-ref-neutral: #080808;
  --x-ref-status-positive: #009600;
  --x-ref-status-caution: #8A8A3A;
  --x-ref-status-negative: #8A8A8A;
  --x-sys-font-heading: 'Oswald', sans-serif; /* proxy for URW DIN Semi-Condensed */
  --x-sys-font-body: Helvetica, Arial, sans-serif;
  --x-bg-page: #080808;
}
